INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-55', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '與竇武、陳蕃等謀誅閹官，武等遇害，肅亦坐黨禁錮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-56', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '時陳蕃為光祿勳，滂執公儀詣蕃，蕃不止之，滂懷恨，投版弃官而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-57', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '延熹九年，黨事起，太尉陳蕃爭之不能得，朝廷寒心，莫敢復言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-58', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及陳蕃、李膺之敗，顒以與蕃、膺善，遂為宦官所陷，乃變姓名，亡匿汝南閒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-068-59', 'p0421', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '建寧元年，太傅陳蕃、大將軍竇武為閹人所害，林宗哭之於野，慟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-068-60', 'p0421', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '又陳蕃喪妻還葬，鄉人畢至，而劭獨不往。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-61', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '今臺閣近臣，尚書令陳蕃，僕射胡廣，尚書朱㝢、荀緄、音古本反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-62', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '武旣輔朝政，常有誅翦宦官之意，太傅陳蕃亦素有謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-63', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '與陳蕃合策戮力，唯德是建，咸得其人，豪賢大姓皆絕望矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-64', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」因大呼曰：「陳蕃、竇武奏白太后廢帝，為大逆！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-65', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '『後年磽』者，陳蕃、竇武等誅，天下大壞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-071-66', 'p0421', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」太尉陳蕃、大將軍竇武連辟，並不到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-072-67', 'p0421', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃與司徒黃琬、司空楊彪，俱帶鈇鑕詣闕上書，追理陳蕃、竇武及諸黨人，以從人望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-076-68', 'p0421', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '並以仁信篤誠，使人不欺；王堂、陳寵委任賢良，而職事自理：王堂任陳蕃、應嗣，陳寵任王渙、鐔顯也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-078-69', 'p0421', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '時竇太后臨朝，后父大將軍武與太傅陳蕃謀誅中官，節與長樂五官史朱瑀、從官史共普、共音恭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-078-70', 'p0421', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '太傅陳蕃、大將軍竇武考其黨與，志清朝政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-102-71', 'p0421', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '永康元年十二月丁丑，桓帝崩，太傅陳蕃，大將軍竇武、尚書令尹勳、黃門令山冰等皆枉死，太白犯心，熒惑留守太微之應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-102-72', 'p0421', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '其八月，太傅陳蕃、大將軍竇武謀欲盡誅諸宦者；其九月辛亥，中常侍曹節、長樂五官史朱瑀覺之，矯制殺蕃、武等，家屬徙日南比景。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-103-73', 'p0421', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」案陳蕃上疏：「宮女多聚不御，憂悲之感，以致水旱之困也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-103-74', 'p0421', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '及太后攝政，為大將軍，與太傅陳蕃合心戮力，惟德是建，印綬所加，咸得其人，豪賢大姓皆絕望矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-104-75', 'p0421', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '陳蕃、劉矩、劉茂上疏諫曰：『古之火皆君弱臣強，極陰之變也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-104-76', 'p0421', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '袁山松書曰：「是時宦豎專朝，鉤黨事起，上尋無嗣，陳蕃、竇武為曹節等所害，天下無復紀綱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-104-77', 'p0421', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '陳蕃諫云：「楚女悲而西宮災，不御宮女，怨之所致也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-107-78', 'p0421', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '奐上疏：「陳蕃、竇氏未被明宥，妖眚之來，皆為此也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-114-79', 'p0421', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '」案：靈帝之初，以陳蕃為太傅，蕃誅，以胡廣代，始不止一人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-001-80', 'p0421', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '先是大將軍竇武、太傅陳蕃謀誅閹官，反為所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-001-81', 'p0421', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '司馬彪九州春秋曰：於是陳蕃子逸與術士平原襄楷會於芬坐，楷曰：「天文不利宦者，黃門、常侍貴族滅矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-010-82', 'p0421', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '顒顯名太學，於是中朝名臣太傅陳蕃、司隷李膺等皆深接之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-051-83', 'p0421', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '少游京師，師事太傅陳蕃，博覽羣書，明於風角，善推災異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-054-84', 'p0421', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後為豫州刺史，辟汝南陳蕃為別駕，潁川李膺、荀緄、杜密、沛國朱㝢為從事，皆天下英俊之士也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-007-0', 'p0422', 'houhanshu', 'a03-007', '《後漢書·卷七》', '自非忠賢力爭，屢折姦鋒，忠賢謂李膺、陳蕃、竇武、黃瓊、朱穆、劉淑、劉陶等，各上書極諫，以折宦官等姦謀之鋒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-1', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '桓帝崩，無子，皇太后與父城門校尉竇武定策禁中，使守光祿大夫劉儵持節，將左右羽林至河閒奉迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-2', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '建寧元年春正月壬午，城門校尉竇武為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-3', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '」使竇武持節，以王青蓋車迎入殿中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-4', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '以前太尉陳蕃為太傅，與竇武及司徒胡廣參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-5', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '九月丁亥，中常侍曹節矯詔誅太傅陳蕃、大將軍竇武及尚書令尹勳、侍中劉瑜、屯騎校尉馮述，皆夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-6', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '太后與竇武密謀欲誅曹節，今武等旣誅，故太后被遷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-7', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '桓帝崩，無子，皇太后與父城門校尉竇武定策禁中，使守光祿大夫劉儵持節，將左右羽林至河閒奉迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-8', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '建寧元年春正月壬午，城門校尉竇武為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-9', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '」使竇武持節，以王青蓋車迎入殿中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-10', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '以前太尉陳蕃為太傅，與竇武及司徒胡廣參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-11', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '九月丁亥，中常侍曹節矯詔誅太傅陳蕃、大將軍竇武及尚書令尹勳、侍中劉瑜、屯騎校尉馮述，皆夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-12', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '太后與竇武密謀欲誅曹節，今武等旣誅，故太后被遷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-009-13', 'p0422', 'houhanshu', 'a03-009', '《後漢書·卷九》', '遣使弔祠故太傅陳蕃、大將軍竇武等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-027-14', 'p0422', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '會病卒，謝承書曰：「靈帝即位，典與竇武、王暢、陳蕃等謀共誅中常侍曹節、侯覽、趙忠等，皆下獄自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-031-15', 'p0422', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '續以忠臣子孫拜郎中，去官後，辟大將軍竇武府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-037-16', 'p0422', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '靈帝即位，太傅陳蕃、大將軍竇武輔政，復徵用之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-039-17', 'p0422', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '靈帝初，太傅陳蕃、大將軍竇武為宦者所誅，咨乃謝病去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-053-18', 'p0422', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '中常侍曹節等專執朝事，新誅太傅陳蕃、大將軍竇武，欲借寵賢德，以釋衆望，乃白徵肱為太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-055-19', 'p0422', 'houhanshu', 'a03-055', '《後漢書·卷五十五》', '萇卒，子宏嗣，為大將軍竇武所立，是為靈帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-056-20', 'p0422', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '太后本遷南宮雲臺，太后父竇武與陳蕃謀誅宦官，反為中常侍曹節矯詔殺武、蕃，遷太后焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-056-21', 'p0422', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '初，郃兄侍中儵，與大將軍竇武同謀俱死，故郃與球相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-057-22', 'p0422', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '二十餘年，靈帝即位，大將軍竇武、太傅陳蕃輔政，徵拜議郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-057-23', 'p0422', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '及帝崩，大將軍竇武欲大誅宦官，乃引瑜為侍中，又以侍中尹勳為尚書令，共同謀畫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-062-24', 'p0422', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '昱後共大將軍竇武謀誅中官，與李膺俱死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-062-25', 'p0422', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '靈帝初，大將軍竇武辟以為掾屬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-064-26', 'p0422', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '時皇后父大將軍竇武援立靈帝，初秉機政，朝議欲加封爵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-065-27', 'p0422', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '時竇太后臨朝，大將軍竇武與太傅陳蕃謀誅宦官，事泄，中常侍曹節等於中作亂，以奐新徵，不知本謀，矯制使奐與少府周靖率五營士圍武。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-065-28', 'p0422', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '故大將軍竇武、太傅陳蕃，或志寧社稷，或方直不回，前以讒勝，並伏誅戮，海內默默，人懷震憤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-065-29', 'p0422', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '陳蕃、竇武奮義草謀，徵會天下，名士有識所共聞也，而張奐見欺豎子，揚戈以斷忠烈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-065-30', 'p0422', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '奐被曹節等矯制，使率五營士圍殺陳蕃、竇武等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-31', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '蕃與后父大將軍竇武，同心盡力，徵用名賢，共參政事，天下之士，莫不延頸想望太平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-32', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '蕃常疾之，志誅中官，會竇武亦有謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-33', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '蕃因與竇武謀之，語在武傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-34', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '適聞其言，而讓蕃曰：「先帝新弃天下，山陵未成，竇武何功，兄弟父子，一門三侯？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-35', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」及遭際會，協策竇武，自謂萬世一遇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-36', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '明年，尚書霍諝、城門校尉竇武並表為請，帝意稍解，乃皆赦歸田里，禁錮終身。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-37', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '竇武、劉淑、陳蕃為「三君」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-38', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃、竇武、王暢、劉表、度尚、郭林宗別有傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-39', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '靈帝旣位，宦官譖淑與竇武等通謀，下獄自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-40', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃為太傅，與大將軍竇武共秉朝政，連謀誅諸宦官，故引用天下名士，乃以膺為長樂少府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-41', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '後竇武等誅，朗以黨被急徵，行至牛渚，自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-42', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '與竇武、陳蕃等謀誅閹官，武等遇害，肅亦坐黨禁錮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-43', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '坐竇武等事，下獄自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-44', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '」乃入洛陽，說城門校尉竇武、尚書霍諝，武等訟之，桓帝以此大赦黨人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-068-45', 'p0422', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '建寧元年，太傅陳蕃、大將軍竇武為閹人所害，林宗哭之於野，慟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-46', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '竇武字游平，扶風平陵人，安豐戴侯融之玄孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-47', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」因大呼曰：「陳蕃、竇武奏白太后廢帝，為大逆！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-48', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '甫兵漸盛，使其士大呼武軍曰：「竇武反，汝皆禁兵，當宿衞宮省，何故隨反者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-49', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '『後年磽』者，陳蕃、竇武等誅，天下大壞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-50', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁紹復說進曰：「前竇武欲誅內寵而反為所害者，以其言語漏泄，而五營百官服畏中人故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-51', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '論曰：竇武、何進藉元舅之資，據輔政之權，內倚太后臨朝之威，外迎羣英乘風之埶，卒而事敗閹豎，身死功穨，為世所悲，豈智不足而權有餘乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-071-52', 'p0422', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」太尉陳蕃、大將軍竇武連辟，並不到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-072-53', 'p0422', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃與司徒黃琬、司空楊彪，俱帶鈇鑕詣闕上書，追理陳蕃、竇武及諸黨人，以從人望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-078-54', 'p0422', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '竇武、何進，位崇戚近，乘九服之嚻怨，協羣英之埶力，九服已見上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-078-55', 'p0422', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '羣英謂劉猛、朱㝢之屬，見竇武傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-078-56', 'p0422', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '太傅陳蕃、大將軍竇武考其黨與，志清朝政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-078-57', 'p0422', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '至戚發憤，方啟專奪之隙，謂竇武謀誅宦者，反為宦者所殺也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-102-58', 'p0422', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '永康元年十二月丁丑，桓帝崩，太傅陳蕃，大將軍竇武、尚書令尹勳、黃門令山冰等皆枉死，太白犯心，熒惑留守太微之應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-102-59', 'p0422', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '其八月，太傅陳蕃、大將軍竇武謀欲盡誅諸宦者；其九月辛亥，中常侍曹節、長樂五官史朱瑀覺之，矯制殺蕃、武等，家屬徙日南比景。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-103-60', 'p0422', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時大將軍竇武謀變廢中官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-104-61', 'p0422', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '袁山松書曰：「是時宦豎專朝，鉤黨事起，上尋無嗣，陳蕃、竇武為曹節等所害，天下無復紀綱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a04-001-62', 'p0422', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '先是大將軍竇武、太傅陳蕃謀誅閹官，反為所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a04-006-63', 'p0422', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：初紹說進曰：「黃門、常侍累世太盛，威服海內，前竇武欲誅之而反為所害，但坐言語漏泄，以五營士為兵故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a03-009-0', 'p0423', 'houhanshu', 'a03-009', '《後漢書·卷九》', '白波賊寇河東，薛瑩書曰：「黃巾郭泰等起於西河白波谷，時謂之白波賊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a03-053-1', 'p0423', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '郭泰別傳曰：「時林宗過薛恭祖，恭祖問曰：『聞足不見袁奉高，車不停軌，鑾不輟軶，從叔度乃彌信宿也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a04-006-2', 'p0423', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '少有大節，郭泰見而奇之，曰：「王生一日千里，王佐之才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a04-010-3', 'p0423', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」事垂就而覺，收顒、攸繫獄，顒憂懼自殺，張璠漢紀曰：顒字伯求，少與郭泰、賈彪等遊學洛陽，泰等與同風好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a04-022-4', 'p0423', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '四方至者車數千乘，自太原郭泰等無不造門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a04-057-5', 'p0423', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '宜遠模仲尼之汎愛，中則郭泰之弘濟，近有益於大道也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-009-0', 'p0424', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二月戊戌，司徒黃琬為太尉，司空楊彪為司徒，光祿勳荀爽為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-009-1', 'p0424', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」夏五月，司空荀爽薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-026-2', 'p0424', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '潁川荀爽深以為美，時人亦服焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-043-3', 'p0424', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '野字子遼，見荀爽薦文。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-053-4', 'p0424', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '今潁川荀爽載病在道，北海鄭玄北面受署。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-054-5', 'p0424', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '司空荀爽見卓意壯，恐害彪等，因從容言曰：「相國豈樂此邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-056-6', 'p0424', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '初平元年，代荀爽為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-062-7', 'p0424', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '論曰：荀爽、鄭玄、申屠蟠俱以儒行為處士，累徵並謝病不詣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-063-8', 'p0424', 'houhanshu', 'a03-063', '《後漢書·卷六十三》', '時潁川荀爽、賈彪，雖俱知名而不相能，爕並交二子，情無適莫，世稱其平正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-066-9', 'p0424', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '辟荀爽、孔融等為從事，上除禁黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-067-10', 'p0424', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '」荀爽甞就謁膺，因為其御，旣還，喜曰：「今日乃得御李君矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-067-11', 'p0424', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及陳蕃免太尉，朝野屬意於膺，荀爽恐其名高致禍，欲令屈節以全亂世，為書貽曰：「乆廢過庭，不聞善誘，陟岵瞻望，惟日為歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-067-12', 'p0424', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '少遊京師，志節慷慨，與同郡荀爽齊名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-067-13', 'p0424', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及董卓秉政，逼顒以為長史，託疾不就，乃與司空荀爽、司徒王允等共謀卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-072-14', 'p0424', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '謂忍性屈情，擢用鄭泰、蔡邕、何顒、荀爽等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-079-15', 'p0424', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '融授鄭玄，玄作易注，荀爽又作易傳，自是費氏興，而京氏遂衰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-084-16', 'p0424', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '南陽陰瑜妻者，潁川荀爽之女也，名采，字女荀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-006-17', 'p0424', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '續漢書曰：太尉黃琬、司徒楊彪、司空荀爽俱詣卓，卓言：「昔高祖都關中，十一世後中興，更都洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-006-18', 'p0424', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '三公並辟，歷豫州刺史，辟荀爽、孔融為從事，遷河南尹、尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-011-19', 'p0424', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '昔司空荀爽，家拜光祿，先儒鄭玄，即授司農，若加備禮，庶必可致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-013-20', 'p0424', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太子書報繇，繇荅書曰：「臣同郡故司空荀爽言：『人當道情，愛我者一何可愛！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-022-21', 'p0424', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '寔之亡也，司空荀爽、太僕令韓融並制緦麻，執子孫禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-037-22', 'p0424', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '以此為貶，則荀爽、陳紀之儔皆應擯棄於世矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-038-23', 'p0424', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-053-24', 'p0424', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '還本郡，舉茂才，公府辟，皆不就，吳書曰：大將軍何進、太尉朱儁、司空荀爽三府辟為掾，皆稱疾不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-009-0', 'p0425', 'houhanshu', 'a03-009', '《後漢書·卷九》', '甲午，豫州牧黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-009-1', 'p0425', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二月戊戌，司徒黃琬為太尉，司空楊彪為司徒，光祿勳荀爽為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-009-2', 'p0425', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，太尉黃琬、司徒楊彪免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-009-3', 'p0425', 'houhanshu', 'a03-009', '《後漢書·卷九》', '李傕殺司隷校尉黃琬，甲子，殺司徒王允，皆滅其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-027-4', 'p0425', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '謙字彥信，初平元年，代黃琬為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-053-5', 'p0425', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '後蟠友人陳郡馮雍坐事繫獄，豫州牧黃琬欲殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-054-6', 'p0425', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '中平六年，代董卓為司空，其冬，代黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-054-7', 'p0425', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '太尉黃琬曰：「此國之大事，楊公之言得無可思？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-066-8', 'p0425', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '自蕃為光祿勳，與五官中郎將黃琬共典選舉，不偏權富，而為埶家郎所譖訴，坐免歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-066-9', 'p0425', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '允見卓禍毒方深，篡逆已兆，密與司隷校尉黃琬、尚書鄭公業等謀共誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-072-10', 'p0425', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃與司徒黃琬、司空楊彪，俱帶鈇鑕詣闕上書，追理陳蕃、竇武及諸黨人，以從人望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-072-11', 'p0425', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '會公卿議，太尉黃琬、司徒楊彪廷爭不能得，而伍瓊、周珌又固諫之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-074-12', 'p0425', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '續漢書曰：「彪代董卓為司空，又代黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-075-13', 'p0425', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '太僕黃琬為豫州牧，宗正劉虞為幽州牧，皆以本秩居職。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-079-14', 'p0425', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '司徒黃琬特辟，不行，終於家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-006-15', 'p0425', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '續漢書曰：太尉黃琬、司徒楊彪、司空荀爽俱詣卓，卓言：「昔高祖都關中，十一世後中興，更都洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-008-16', 'p0425', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '英雄記曰：虞讓太尉，因薦衞尉趙謨、益州牧劉焉、豫州牧黃琬、南陽太守羊續，並任為公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-009-17', 'p0425', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '時豫州刺史黃琬欲害太祖，太祖避之而邵獨遇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-029-18', 'p0425', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '沛相陳珪舉孝廉，太尉黃琬辟，皆不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-042-19', 'p0425', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '漢末大亂，敏隨姊奔荊州，姊夫黃琬是劉璋祖母之姪，故璋遣迎琬妻，敏遂俱與姊入蜀，常為璋賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-049-20', 'p0425', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '比至，宮已免，黃琬代為司徒，甚禮遇壹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-007-0', 'p0426', 'houhanshu', 'a03-007', '《後漢書·卷七》', '九月，司空黃瓊免，大鴻臚劉寵為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-full-1', 'p0426', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月，司空王暢免，宗正劉寵為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-full-2', 'p0426', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空劉寵為司徒，大鴻臚許栩為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-full-3', 'p0426', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '六月，司徒劉寵為太尉，太常許訓為司徒，訓字季師，平輿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-full-4', 'p0426', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，太尉劉寵免，太僕郭禧為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-5', 'p0426', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月，司空王暢免，宗正劉寵為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-6', 'p0426', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空劉寵為司徒，大鴻臚許栩為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-7', 'p0426', 'houhanshu', 'a03-008', '《後漢書·卷八》', '六月，司徒劉寵為太尉，太常許訓為司徒，訓字季師，平輿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-8', 'p0426', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，太尉劉寵免，太僕郭禧為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-015-9', 'p0426', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '謝承書曰：「安衆侯劉寵，長沙定王五代孫，南陽宗室也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-046-10', 'p0426', 'houhanshu', 'a03-046', '《後漢書·卷四十六》', '建寧二年，代劉寵為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-057-11', 'p0426', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '今之四公，唯司空劉寵斷斷守善，餘皆素餐致寇之人，四公謂劉矩為太尉，許訓為司徒，胡廣為太傅及寵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-067-12', 'p0426', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '以前太尉劉寵、司隷校尉許冰、幽州刺史楊熙、涼州刺史劉恭、益州刺史龐艾清亮在公，薦舉升進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-076-13', 'p0426', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '衞颯　任延　王景　秦彭　王渙　許荊　孟甞　弟五訪　劉矩　劉寵　仇香　童恢');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-076-14', 'p0426', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '劉寵字祖榮，東萊牟平人，齊悼惠王之後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-077-15', 'p0426', 'houhanshu', 'a03-077', '《後漢書·卷七十七》', '辟司徒劉寵府，舉高第。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-081-16', 'p0426', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '太守劉寵舉就孝廉，光祿主事，病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-112-17', 'p0426', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '三齊記曰：「南有蹲犬山，山似犬蹲，有神，劉寵出西都，經此山，山犬吠之，寵曰『山神謂我人也』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-0', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '己未，以平東將軍、琅邪王睿為安東將軍、都督揚州江南諸軍事、假節，鎮建鄴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-1', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '鎮東將軍周馥表迎大駕遷都壽陽，越使裴頠討馥，為馥所敗，走保東城，請救於琅邪王睿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-2', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '戊寅，安東將軍、琅邪王睿使將軍甘卓攻鎮東將軍周馥於壽春，馥衆潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-3', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '進司空王浚為大司馬，征西大將軍、南陽王模為太尉，太子太傅傅祗為司徒，尚書令荀藩為司空，安東將軍、琅邪王睿為鎮東大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-4', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '癸丑，鎮東大將軍、琅邪王睿上尚書，檄四方以討石勒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-5', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '五月壬辰，以鎮東大將軍、琅邪王睿為侍中、左丞相、大都督陝東諸軍事，大司馬、南陽王保為右丞相、大都督陝西諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-6', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '二月丙子，進左丞相、琅邪王睿為大都督、督中外諸軍事，右丞相、南陽王保為相國，司空荀組為太尉，大將軍劉琨為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-7', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '三月，琅邪王睿承制改元，稱晉王于建康。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a03-075-0', 'p0429', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '州大吏趙韙等貪璋溫仁，立為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a03-075-1', 'p0429', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '趙韙之在巴中，甚得衆心，璋委之以權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-2', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '扶亦求為蜀郡西部屬國都尉，及太倉令會巴西趙韙去官，俱隨焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-3', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '州大吏趙韙等貪璋溫仁，共上璋為益州刺史，詔書因以為監軍使者，領益州牧，以韙為征東中郎將，率衆擊劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-4', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋使趙韙進攻荊州，屯朐䏰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-5', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '後羲與璋情好攜隙，趙韙稱兵內向，衆散見殺，皆由璋明斷少而外言入故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-6', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '趙韙素得人心，璋委任之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a03-075-0', 'p0430', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '璋怒，殺魯母及弟，而遣其將龐羲等攻魯，數為所破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-1', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '議郎河南龐羲與焉通家，乃募將焉諸孫入蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-2', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋累遣龐羲等攻魯，數為所破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-3', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '英雄記曰：龐羲與璋有舊，又免璋諸子於難，故璋厚德羲，以羲為巴西太守，遂專權勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-4', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '後松復說璋曰：「今州中諸將龐羲、李異等皆恃功驕豪，欲有外意，不得豫州，則敵攻其外，民攻其內，必敗之道也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-5', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '初，璋長子循妻，龐羲女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-032-6', 'p0430', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '秋，羣下上先主為漢中王，表於漢帝曰：「平西將軍都亭侯臣馬超、左將軍長史領鎮軍將軍臣許靖、營司馬臣龐羲、議曹從事中郎軍議中郎將臣射援、三輔決錄注曰：援字文雄，扶風人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-045-7', 'p0430', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」芝聞巴西太守龐羲好士，往依焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-045-8', 'p0430', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '巴西太守龐羲以天下擾亂，郡宜有武衞，頗招合部曲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a03-074-0', 'p0431', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '瓚輕其兵少，縱騎騰之，義兵伏楯下，一時同發，瓚軍大敗，斬其所置兾州刺史嚴綱，獲甲首千餘級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a03-082-1', 'p0431', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '昔為陪隷，與臣從事，奮忠毅之操，躬史魚之節，董臣嚴綱，勗臣懦弱，董，督也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a04-006-2', 'p0431', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '義兵皆伏楯下不動，未至數十步，乃同時俱起，揚塵大叫，直前衝突，彊弩雷發，所中必倒，臨陣斬瓚所署兾州刺史嚴綱甲首千餘級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a04-008-3', 'p0431', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '以嚴綱為兾州，田楷為青州，單經為兖州，置諸郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a04-047-4', 'p0431', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '祕所領都督廖式殺臨賀太守嚴綱等，自稱平南將軍，與弟潛共攻零陵、桂陽，及搖動交州、蒼梧、鬱林諸郡，衆數萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a03-067-0', 'p0433', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '以儉及檀彬、褚鳳、張肅、薛蘭、馮禧、魏玄、徐乾為「八俊」，田林、張隱、劉表、薛郁、王訪、劉祇、宣靖、公緒恭為「八顧」，公緒，姓也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a03-074-1', 'p0433', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '布將薛蘭、李封屯鉅野，操攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a04-001-2', 'p0433', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，布將薛蘭、李封屯鉅野，太祖攻之，布救蘭，蘭敗，布走，遂斬蘭等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a04-010-3', 'p0433', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今以破李封、薛蘭，若分兵東擊陳宮，宮必不敢西顧，以其閒勒兵收熟麥，約食畜穀，一舉而布可破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a04-018-4', 'p0433', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '布別駕薛蘭、治中李封招乾，欲俱叛，乾不聽，遂殺乾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a03-036-0', 'p0434', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '帝以元新忿爭，乃用其次司隷從事李封，於是諸儒以左氏之立，論議讙譁，自公卿以下數廷爭之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a03-074-1', 'p0434', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '布將薛蘭、李封屯鉅野，操攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a04-001-2', 'p0434', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，布將薛蘭、李封屯鉅野，太祖攻之，布救蘭，蘭敗，布走，遂斬蘭等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a04-010-3', 'p0434', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今以破李封、薛蘭，若分兵東擊陳宮，宮必不敢西顧，以其閒勒兵收熟麥，約食畜穀，一舉而布可破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a04-018-4', 'p0434', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '布別駕薛蘭、治中李封招乾，欲俱叛，乾不聽，遂殺乾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-008-full-0', 'p0437', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '黑山賊張牛角等十餘輩並起，所在寇鈔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-008-1', 'p0437', 'houhanshu', 'a03-008', '《後漢書·卷八》', '黑山賊張牛角等十餘輩並起，所在寇鈔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-009-2', 'p0437', 'houhanshu', 'a03-009', '《後漢書·卷九》', '黃巾起，燕合聚少年為羣盜，萬餘人，博陵人張牛角為主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-058-3', 'p0437', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '博陵張牛角之起，衆次癭陶，牛角為飛矢所中，且死，告其衆曰：「必以燕為帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-074-4', 'p0437', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '黃巾賊起，燕聚少年為羣盜，博陵張牛角亦起與燕合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a04-008-5', 'p0437', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '博陵張牛角亦起衆，自號將兵從事，與燕合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0439-a03-071-0', 'p0439', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '雷公、浮雲、飛燕、白雀、楊鳳、于毒、五鹿、李大目、白繞、畦固、苦唒之徒，九州春秋「唒」作「蝤」，音才由反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0439-a04-001-1', 'p0439', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '黑山賊于毒、白繞、眭固等眭，申隨反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0439-a04-001-2', 'p0439', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十餘萬衆略魏郡、東郡，王肱不能禦，太祖引兵入東郡，擊白繞於濮陽，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0440-a03-070-0', 'p0440', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '時融為管亥所圍，慈從遼東還，母謂之曰：「汝與孔北海未甞相見，至汝行後，贍恤殷勤，過於故舊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0440-a04-049-1', 'p0440', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '時融以黃巾寇暴，出屯都昌，為賊管亥所圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0440-a04-049-2', 'p0440', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '今管亥暴亂，北海被圍，孤窮無援，危在旦夕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0442-a04-032-0', 'p0442', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '紹遣先主將本兵復至汝南，與賊龔都等合，衆數千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0443-a04-001-0', 'p0443', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0444-a04-001-0', 'p0444', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0445-a04-001-0', 'p0445', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0445-a04-017-1', 'p0445', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征黃巾劉辟、黃邵等，屯版梁，邵等夜襲太祖營，禁帥麾下擊破之，斬辟、邵等，盡降其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-024-0', 'p0446', 'houhanshu', 'a03-024', '《後漢書·卷二十四》', '明年，防復以病乞骸骨，詔賜故中山王田廬，中山王焉以郭太后少子故，獨留京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-042-1', 'p0446', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '焉以郭太后少子故，獨留京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-042-2', 'p0446', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '」帝以焉郭太后偏愛，特加恩寵，獨得往來京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-068-3', 'p0446', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '郭太字林宗，范曄父名泰，故改為此「太」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-072-4', 'p0446', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，靈帝末，黃巾餘黨郭太等復起西河白波谷，轉寇太原，遂破河東，百姓流轉三輔，號為「白波賊」，衆十餘萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a04-003-5', 'p0446', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '送詣京師，郭太后愛養之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a04-009-6', 'p0446', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '奏使郭太后出居別宮，及遣樂安王使北詣鄴，又遣文欽令還淮南，皆謐之計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-001-0', 'p0447', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '黑山賊于毒、白繞、眭固等眭，申隨反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-001-1', 'p0447', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖要擊眭固，又擊匈奴於夫羅於內黃，皆大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-001-2', 'p0447', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張楊將楊醜殺楊，眭固又殺醜，以其衆屬袁紹，屯射犬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-001-3', 'p0447', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '迴戈東征，呂布就戮，乘轅將返，張楊殂斃，眭固伏罪，張繡稽服，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-008-4', 'p0447', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '其將楊醜殺楊以應太祖，楊將眭固殺醜，將其衆，欲北合袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-014-5', 'p0447', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自在軍旅，十有餘年，行同騎乘，坐共幄席，東禽呂布，西取眭固，斬袁譚之首，平朔土之衆，踰越險塞，盪定烏丸，震威遼東，以梟袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-017-6', 'p0447', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征張繡於安衆，圍呂布於下邳，破別將，擊眭固於射犬，攻劉備於沛，皆破之，拜討寇校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-017-7', 'p0447', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復從攻張繡於穰，禽呂布於下邳，別與史渙、曹仁攻眭固於射犬，破斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0448-a03-071-0', 'p0448', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '雷公、浮雲、飛燕、白雀、楊鳳、于毒、五鹿、李大目、白繞、畦固、苦唒之徒，九州春秋「唒」作「蝤」，音才由反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0448-a03-101-1', 'p0448', 'houhanshu', 'a03-101', '《二十四史-後漢書-志第十一‧天文中》', '是時中常侍高梵、張防、將作大匠翟酺、尚書令高堂芝、僕射張敦、尚書尹就、郎姜述、楊鳳等，及兖州刺史鮑就、使匈奴中郎將張國、金城太守張篤、敦煌太守張朗，相與交通，漏泄，就、述棄巿，梵、防、酺、芝、敦、鳳、就、國皆抵罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0448-a04-008-2', 'p0448', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0448-a04-008-3', 'p0448', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '靈帝不能討，乃遣使拜楊鳳為黑山校尉，領諸山賊，得舉孝廉計吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-003-0', 'p0449', 'houhanshu', 'a03-003', '《後漢書·卷三》', '五月戊申，詔曰：「乃者鳳皇、黃龍、鸞鳥比集七郡，孫柔之瑞應圖曰：「鸞鳥者，赤神之精，鳳皇之佐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-003-1', 'p0449', 'houhanshu', 'a03-003', '《後漢書·卷三》', '九月壬辰，詔：「鳳皇、黃龍所見亭部無出二年租賦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-003-2', 'p0449', 'houhanshu', 'a03-003', '《後漢書·卷三》', '」古今注云：「黃龍見洛陽元延亭部。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-3', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '舍利之獸從西方來，戲于庭，入前殿，激水化成比目魚，嗽水作霧，化成黃龍，長八丈，出水遨戲於庭，炫燿日光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-4', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '辛卯，九真言黃龍見無功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-5', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '辛亥，濟南上言黃龍見歷城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-6', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '十二月乙未，琅邪言黃龍見諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-7', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '四年春正月壬午，東郡言黃龍二、麒麟一見濮陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-007-8', 'p0449', 'houhanshu', 'a03-007', '《後漢書·卷七》', '八月，濟陰言黃龍見句陽，縣名，屬濟陰郡，左傳曰「盟于句瀆之丘」是也，故城在今曹州乘氏縣北，一名穀丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-007-9', 'p0449', 'houhanshu', 'a03-007', '《後漢書·卷七》', '己酉，南宮嘉德署黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-007-10', 'p0449', 'houhanshu', 'a03-007', '《後漢書·卷七》', '續漢志曰：「時人欲就沲浴，見沲水濁，因戲相恐：『此中有黃龍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-036-11', 'p0449', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '章帝時，鳳皇見百三十九，騏麟五十二，白虎二十九，黃龍三十四，神雀、白燕等史官不可勝紀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-043-12', 'p0449', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '而明年嚴鮪謀立清河王蒜，又黃龍二見沛國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-048-13', 'p0449', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '帝東巡狩，鳳皇黃龍並集，終贊頌嘉瑞，上述祖宗鴻業，凡十五章，奏上，詔貰還故郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-069-14', 'p0449', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '閒者有嘉禾、芝草、黃龍之見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-071-15', 'p0449', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-074-16', 'p0449', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遂尋山北行，進擊諸賊左髭丈八等，皆斬之，又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，復斬數萬級，皆屠其屯壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-078-17', 'p0449', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '中黃門孫程、王康、長樂太官丞王國、中黃門黃龍、彭愷、孟叔、李建、王成、張賢、史汎、馬國、王道、李元、楊佗、佗音駝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-078-18', 'p0449', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '其封程為浮陽侯，食邑萬戶；康為華容侯，國為酈侯，各九千戶；黃龍為湘南侯，五千戶；彭愷為西平昌侯，西平昌，諸縣，屬平原郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-078-19', 'p0449', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '黃龍、楊佗、孟叔、李建、張賢、史汎、王道、李元、李剛九人與阿母山陽君宋娥更相貨賂，求高官增邑，又誣罔中常侍曹騰、孟賁等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-082-20', 'p0449', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '舜禮壇于河畔，沈璧，禮畢，至于下昃，黃龍負卷舒圖，出水壇畔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-086-21', 'p0449', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '盟曰：「秦犯夷，輸黃龍一雙；夷犯秦，輸清酒一鍾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-092-22', 'p0449', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '太宗遵修，三階以平，黃龍以至，刑犴以錯，五是以備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-095-23', 'p0449', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '以戊、己日為大黃龍一，長五丈，居中央；又為小龍四，各長二丈五尺，於中央，皆南鄉，其閒相去五尺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-095-24', 'p0449', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '畢，化成黃龍，長八丈，出水遨戲於庭，炫燿日光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-103-25', 'p0449', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '宣帝黃龍元年，未央宮雌雞化為雄，不鳴無距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-104-26', 'p0449', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '八年二月己酉，南宮嘉德署、黃龍、千秋萬歲殿皆火。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-107-27', 'p0449', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '安帝延光三年，濟南言黃龍見歷城，琅邪言黃龍見諸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-107-28', 'p0449', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '明年正月，東郡又言黃龍二見濮陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-107-29', 'p0449', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '永康元年八月，巴郡言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-107-30', 'p0449', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '甞見堅語云：「時民以天熱，欲就池浴，見池水濁，因戲相恐『此中有黃龍』，語遂行人間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-31', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '初，漢熹平五年，黃龍見譙，光祿大夫橋玄問太史令單颺：「此何祥也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-32', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '三月，黃龍見譙，登聞之曰：「單颺之言，其驗茲乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-33', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '辛亥，太史丞許芝條魏代漢見讖緯於魏王曰：「易傳曰：『聖人受命而王，黃龍以戊己日見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-34', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '』七月四日戊寅，黃龍見，此帝王受命之符瑞最著明者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-35', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '是以黃龍數見，鳳皇仍翔，麒麟皆臻，白虎效仁，前後獻見於郊甸；甘露醴泉，奇獸神物，衆瑞並出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-003-36', 'p0449', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '景初元年春正月壬辰，山茌縣言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-003-37', 'p0449', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '又鑄黃龍、鳳皇各一，龍高四丈，鳳高三丈餘，置內殿前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-003-38', 'p0449', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '若今宮室狹小，當廣大之，猶宜隨時，不妨農務，況乃作無益之物，黃龍、鳳皇，九龍、承露盤，土山、淵池，此皆聖明之所不興也，其功參倍於殿舍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-004-39', 'p0449', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '戊戌，黃龍見于鄴井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-004-40', 'p0449', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是歲，青龍、黃龍仍見頓丘、冠軍、陽夏縣界井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-004-41', 'p0449', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '四年春正月，黃龍二，見寧陵縣界井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-004-42', 'p0449', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '十二月甲申，黃龍見華陰縣井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-006-43', 'p0449', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，皆屠其屯壁，奔走得脫，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-008-44', 'p0449', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-020-45', 'p0449', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '其年，黃龍見鄴西漳水，衮上書贊頌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-021-46', 'p0449', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '黃龍不反于涸澤，鳳皇不離其罻羅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-025-47', 'p0449', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '帝愈增崇宮殿，彫飾觀閣，鑿太行之石英，采穀城之文石，起景陽山於芳林之園，建昭陽殿於太極之北，鑄作黃龍鳳皇奇偉之獸，飾金墉、陵雲臺、陵霄闕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-029-48', 'p0449', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '昔夏禹文明，不怪於黃龍，周武信時，不惑於暴風，今明府道德高妙，神不懼妖，自天祐之，吉無不利，願安百祿以光休寵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-032-49', 'p0449', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '間黃龍見武陽赤水，九日乃去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-032-50', 'p0449', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孝經援神契曰『德至淵泉則黃龍見』，龍者，君之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-047-51', 'p0449', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '黃龍元年春，公卿百司皆勸權正尊號。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-047-52', 'p0449', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏四月，夏口、武昌並言黃龍、鳳凰見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-047-53', 'p0449', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」三月，海鹽縣言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-047-54', 'p0449', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏四月，雨雹，雲陽言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-048-55', 'p0449', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '秋七月，始新言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-048-56', 'p0449', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '六年夏四月，泉陵言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-053-57', 'p0449', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '黃龍三年，建昌侯慮為鎮軍大將軍，屯半州，以綜為長史，外掌衆事，內授書籍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-054-58', 'p0449', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '黃龍元年，封都鄉侯，後以罪徙廬陵郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-055-59', 'p0449', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹仁出濡須，戰有功，又從攻破曹休，進位裨將軍，黃龍二年卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-055-60', 'p0449', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時山陰宿賊黃龍羅、周勃聚黨數千人，策自出討，襲身斬羅、勃首，還拜別部司馬，授兵數千，遷揚武都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-056-61', 'p0449', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃龍元年，拜車騎將軍、右護軍，領兖州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-056-62', 'p0449', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃龍元年，拜桓前將軍，領青州牧，假節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-057-63', 'p0449', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '黃龍元年，權遷都建業，徵據尚公主，拜左將軍，封雲陽侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-058-64', 'p0449', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃龍元年，拜上大將軍、右都護。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-059-65', 'p0449', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '黃龍元年，權稱尊號，登為皇太子，以恪為左輔，休右弼，譚為輔正，表為翼正都尉，是為四友，而謝景、范慎、刁玄、羊衜等皆為賔客，衜音道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-060-66', 'p0449', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '黃龍元年，遷衞將軍、左護軍、徐州牧，吳書曰：初，琮為將甚勇決，當敵臨難，奮不顧身。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-060-67', 'p0449', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '黃龍三年，以南土清定，召岱還屯長沙漚口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-68', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '黃武八年夏，黃龍見夏口，於是權稱尊號，因瑞改元。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-69', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '又作黃龍大牙，常在中軍，諸軍進退，視其所向，命綜作賦曰：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-70', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '四靈旣布，黃龍處中，周制日月，實曰太常，桀然特立，六軍所望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-71', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '軍欲轉向，黃龍先移，金鼓不鳴，寂然變施，闇謨若神，可謂祕奇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-72', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '在昔周室，赤烏銜書，今也大吳，黃龍吐符。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-064-73', 'p0449', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '初，權黃龍元年遷都建業，二年築東興隄遏湖水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-003-74', 'p0449', 'jinshu', 'a05-003', '《晉書·卷三》', '是歲，鳳皇六、青龍十、黃龍九、麒麟各一見于郡國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-003-75', 'p0449', 'jinshu', 'a05-003', '《晉書·卷三》', '戊申，青龍、黃龍各一見于魯國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-010-76', 'p0449', 'jinshu', 'a05-010', '《晉書·卷十》', '慕容寶將慕容詳僭即皇帝位于中山，寶奔黃龍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-010-77', 'p0449', 'jinshu', 'a05-010', '《晉書·卷十》', '丙戌，慕容盛僭即皇帝位於黃龍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-011-78', 'p0449', 'jinshu', 'a05-011', '《晉書·卷十一》', '軒轅，黃帝之神，黃龍之體也；后妃之主，士職也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-004-0', 'p0450', 'houhanshu', 'a03-004', '《後漢書·卷四》', '二月，大將軍竇憲遣左校尉耿夔出居延塞，居延，縣，屬張掖郡，居延澤在東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-004-1', 'p0450', 'houhanshu', 'a03-004', '《後漢書·卷四》', '遣大將軍左校尉耿夔授璽綬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-005-2', 'p0450', 'houhanshu', 'a03-005', '《後漢書·卷五》', '秋七月丁酉，初復右校令、左校丞官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-008-full-3', 'p0450', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-008-4', 'p0450', 'houhanshu', 'a03-008', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-019-5', 'p0450', 'houhanshu', 'a03-019', '《後漢書·卷十九》', '三年，憲復出河西，以夔為大將軍左校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-026-6', 'p0450', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '政任威刑，為受罰者所奏，坐論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-026-7', 'p0450', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '左校，署名，屬將作也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-031-8', 'p0450', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '及謙至，部案得其臧，論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-038-9', 'p0450', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '遷，故車騎將軍單超之弟，中官相黨，遂共誹章誣緄，坐與司隷校尉李膺、大司農劉祐俱輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-043-10', 'p0450', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '左校，署名，屬將作，掌左工徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-043-11', 'p0450', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '由是內官咸共恚疾，謗讟煩興，讒隙仍作，極其刑讁，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-051-12', 'p0450', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '初仕郡，未知名，河南尹龐奮見而竒之，舉為孝廉，拜左校令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-051-13', 'p0450', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '臣伏見故左校令河南龐參，勇謀不測，卓爾竒偉，高才武略，有魏尚之風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-054-14', 'p0450', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '今盛夏土王，而攻山採石，其大匠左校別部將作合數十處，續漢志將作大匠，秩二千石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-054-15', 'p0450', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」而秉竟坐輸作左校，以乆旱赦出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-058-16', 'p0450', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '書奏，防流涕訴帝，詡坐論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-063-17', 'p0450', 'houhanshu', 'a03-063', '《後漢書·卷六十三》', '爕以謗毀宗室，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-064-18', 'p0450', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '行賂於侯覽，得減死罪一等，論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-065-19', 'p0450', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '官屬欲賦斂請謝，規誓而不聽，遂以餘寇不絕，坐繫廷尉，論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-065-20', 'p0450', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '漢官儀曰，左校署屬將作大匠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-065-21', 'p0450', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '又臣昔論輸左校時，太學生張鳳等上書訟臣，是為黨人所附也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-065-22', 'p0450', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '郭閎歸罪於熲，熲坐徵下獄，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-066-23', 'p0450', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '又山陽太守翟超，沒入中常侍侯覽財產，東海相黃浮，誅殺下邳令徐宣，超、浮並坐髡鉗，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-067-24', 'p0450', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '膺表欲桉其罪，元羣行賂宦豎，膺反坐輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-067-25', 'p0450', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '竊見左校弛刑徒前廷尉馮緄、大司農劉祐、河南尹李膺等，執法不撓，誅舉邪臣，肆之以法，肆，陳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-067-26', 'p0450', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '桓帝大怒，論祐輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-067-27', 'p0450', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '騰使大將軍梁兾為書請之，衍不荅，鼎竟坐輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-071-28', 'p0450', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '儁乃羸服閒行，輕齎數百金到京師，賂主章吏，遂得刊定州奏，故端得輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-071-29', 'p0450', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-074-30', 'p0450', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八人，謂之西園軍，皆統於碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-074-31', 'p0450', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遂尋山北行，進擊諸賊左髭丈八等，皆斬之，又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，復斬數萬級，皆屠其屯壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-078-32', 'p0450', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '節等怨猛不已，使熲以它事奏猛，抵罪輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-089-33', 'p0450', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '由是始置度遼營，以中郎將吳棠行度遼將軍事，副校尉來苗、左校尉閻章、右校尉張國將黎陽虎牙營士屯五原曼柏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-092-34', 'p0450', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '詔書報，恂、誠各以二月奉贖罪，整適作左校二月。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-093-35', 'p0450', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '臣初決罪雒陽詔獄，生出牢戶，顧念元初中故尚書郎張俊，坐漏泄事，當伏重刑，已出穀門，復聽讀鞠，詔書馳救，減罪一等，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-117-36', 'p0450', 'houhanshu', 'a03-117', '《二十四史-後漢書-志第二十七‧百官四》', '」案紀，光武改青巾左校尉為越騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a04-006-37', 'p0450', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，皆屠其屯壁，奔走得脫，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a04-008-38', 'p0450', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a04-008-39', 'p0450', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張璠漢紀云：又有左校、郭大賢、左髭丈八三部也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0451-a03-071-0', 'p0451', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0451-a03-074-1', 'p0451', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遂尋山北行，進擊諸賊左髭丈八等，皆斬之，又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，復斬數萬級，皆屠其屯壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0451-a04-006-2', 'p0451', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，皆屠其屯壁，奔走得脫，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0451-a04-008-3', 'p0451', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張璠漢紀云：又有左校、郭大賢、左髭丈八三部也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0452-a03-071-0', 'p0452', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0452-a03-074-1', 'p0452', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遂尋山北行，進擊諸賊左髭丈八等，皆斬之，又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，復斬數萬級，皆屠其屯壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0452-a04-006-2', 'p0452', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '遂尋山北行，薄擊諸賊左髭丈八等，皆斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0452-a04-008-3', 'p0452', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張璠漢紀云：又有左校、郭大賢、左髭丈八三部也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0454-a03-071-0', 'p0454', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0454-a03-074-1', 'p0454', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遂尋山北行，進擊諸賊左髭丈八等，皆斬之，又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，復斬數萬級，皆屠其屯壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0454-a04-006-2', 'p0454', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，皆屠其屯壁，奔走得脫，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0455-a03-071-0', 'p0455', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0455-a03-071-1', 'p0455', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '其大聲者稱雷公，騎白馬者為張白騎，輕便者言飛燕，多髭者號于氐根，左氏傳曰：「于思于思，棄甲復來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0455-a04-008-2', 'p0455', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '典略曰：黑山、黃巾諸帥，本非冠蓋，自相號字，謂騎白馬者為張白騎，謂輕捷者為張飛燕，謂聲大者為張雷公，其饒鬚者則自稱于羝根，其眼大者自稱李大目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0455-a04-018-3', 'p0455', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '後張白騎叛於弘農，悳復隨騰征之，破白騎於兩殽閒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0456-a03-071-0', 'p0456', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0456-a03-074-1', 'p0456', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遂尋山北行，進擊諸賊左髭丈八等，皆斬之，又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，復斬數萬級，皆屠其屯壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0456-a04-006-2', 'p0456', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，皆屠其屯壁，奔走得脫，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0456-a04-008-3', 'p0456', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0456-a05-005-4', 'p0456', 'jinshu', 'a05-005', '《晉書·卷五》', '股肱非挑戰之秋，劉石有滔天之勢，療飢中斷，嬰戈外絕，兩京淪狄，再駕徂戎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0457-a03-054-0', 'p0457', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及操自平漢中，欲因討劉備而不得進，欲守之又難為功，護軍不知進止何依。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0457-a03-071-1', 'p0457', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0457-a03-072-2', 'p0457', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，隴西人宗建在枹罕，自稱「河首平漢王」，建以居河上流，故稱「河首」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0457-a03-074-3', 'p0457', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」賊有陶升者，自號「平漢將軍」，英雄記曰：「升故為內黃小吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0457-a04-001-4', 'p0457', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，隴西宋建自稱河首平漢王，聚衆枹罕，改元，置百官，三十餘年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0457-a04-008-5', 'p0457', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0457-a04-009-6', 'p0457', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '初，枹罕宋建因涼州亂，自號河首平漢王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0457-a04-026-7', 'p0457', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '從平漢中，太祖還，留招為中護軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a03-017-0', 'p0458', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '季文誠能覺悟成敗，亟定大計，論功古人，亟，急也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a03-019-1', 'p0458', 'houhanshu', 'a03-019', '《後漢書·卷十九》', '今吏士死亡者多，弇願歸幽州，益發精兵，以集其大計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a03-063-2', 'p0458', 'houhanshu', 'a03-063', '《後漢書·卷六十三》', '固以清河王蒜年長有德，欲立之，謂梁兾曰：「今當立帝，宜擇長年高明有德，任親政事者，願將軍審詳大計，察周、霍之立文、宣，周勃立文帝，霍光立宣帝也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a03-066-3', 'p0458', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '「宋翼豎儒，不足議大計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a03-069-4', 'p0458', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」又與武、蕃書，以星辰錯繆，不利大臣，宜速斷大計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a03-071-5', 'p0458', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a03-075-6', 'p0458', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '於是往說布曰：「曹公奉迎天子，輔贊國政，將軍宜與協同策謀，共存大計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a03-082-7', 'p0458', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '將作大匠翟酺上郃「潛圖大計，以安社稷」，於是錄陰謀之功，封郃涉都侯，辭讓不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-004-8', 'p0458', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '興移書日南州郡，開示大計，兵臨合浦，告以禍福；遣都尉唐譜等詣進乘縣，因南中都督護軍霍弋上表自陳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-006-9', 'p0458', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」授曰：「今迎朝廷，至義也，又於時宜大計也，若不早圖，必有先人者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-012-10', 'p0458', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '後歸曹公，遂為所待，軍國大計常與焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-014-11', 'p0458', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '司馬宣王及濟說太祖曰：「于禁等為水所沒，非戰攻之失，於國家大計未足有損。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-016-12', 'p0458', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '今者外有伺隙之寇，內有貧曠之民，陛下當大計天下之損益，政事之得失，誠不可以怠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-027-13', 'p0458', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '周制冢宰之職，大計群吏之治而誅賞，又無校比之制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-045-14', 'p0458', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '益部耆舊雜記曰：諸葛亮於武功病篤，後主遣福省侍，遂因諮以國家大計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-046-15', 'p0458', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '去冬傳有大計，無不悚懼；旋知供備貢獻，萬夫解惑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-047-16', 'p0458', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '惟將軍天姿特達，兼包文武，觀時覩變，審於去就，踰越險阻，顯致赤心，肇建大計，為天下先，元勳巨績，侔於古人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-048-17', 'p0458', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '丙申，詔曰：「大將軍忠款內發，首建大計以安社稷，卿士內外，咸贊其議，並有勳勞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-054-18', 'p0458', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '愚謂大計宜徙備置吳，盛為築宮室，多其美女玩好，以娛其耳目，分此二人，各置一方，使如瑜者得挾與攻戰，大事可定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-054-19', 'p0458', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '願早定大計，莫用衆人之議也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-054-20', 'p0458', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」權歎息曰：「此諸人持議，甚失孤望；今卿廓開大計，正與孤同，此天以卿賜我也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a04-056-21', 'p0458', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '子敬英爽有殊略，孤始與一語，便及大計，與禹相似，故比之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a05-001-22', 'p0458', 'jinshu', 'a05-001', '《晉書·卷一》', '帝諫曰：「禁等為水所沒，非戰守之所失，於國家大計未有所損，而便遷都，既示敵以弱，又淮沔之人大不安矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a05-009-23', 'p0458', 'jinshu', 'a05-009', '《晉書·卷九》', '皇太后深懼皇基，時定大計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a05-034-24', 'p0458', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '而陛下過聽，便用委棄大計，縱敵患生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a05-036-full-25', 'p0458', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '」玠啟諭深至，爲門戶大計，母涕泣從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a05-036-full-26', 'p0458', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a05-036-27', 'p0458', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '」玠啟諭深至，爲門戶大計，母涕泣從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0458-a05-036-28', 'p0458', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-002-0', 'p0459', 'jinshu', 'a05-002', '《晉書·卷二》', '命使持節、兼司徒、司隸校尉陔即授印綬策書，金獸符第一至第五，竹使符第七至第十。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-004-1', 'p0459', 'jinshu', 'a05-004', '《晉書·卷四》', '唯僕射荀藩、司隸劉暾、太常鄭球、河南尹周馥與其遺官在洛陽，為留臺，承制行事，號為東西臺焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-004-2', 'p0459', 'jinshu', 'a05-004', '《晉書·卷四》', '高密王簡為鎮南將軍，領司隸校尉，權鎮洛陽；東中郎將模為寧北將軍、都督冀州，鎮于鄴；鎮南大將軍劉弘領荊州，以鎮南土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-004-3', 'p0459', 'jinshu', 'a05-004', '《晉書·卷四》', '戊申，驃騎、范陽王虓殺司隸校尉邢喬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-011-4', 'p0459', 'jinshu', 'a05-011', '《晉書·卷十一》', '四曰司祿、司中，司隸賞功進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-5', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '省朔方刺史，合之於司隸，凡十三部，其與西漢不同者，司隸校尉部郡治河南，朔方隸於并部。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-6', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '省司隸置司州，別立梁、秦、寧、平四州，仍吳之廣州，凡十九州，司、冀、兗、豫、荊、徐、揚、青、幽、平、并、雍、涼、秦、梁、益、寧、交、廣州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-7', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '及漢武帝，初置司隸校尉，所部三輔、三河諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-8', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '及光武都洛陽，司隸所部與前漢不異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-9', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '魏氏受禪，即都漢宮，司隸所部河南、河東、河內、弘農并冀州之平陽，合五郡，置司州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-10', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '晉仍居魏都，乃以三輔還屬雍州，分河南立滎陽，分雍州之京兆立上洛，廢東郡立頓丘，遂定名司州，以司隸校尉統之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-11', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '司隸校尉、河南尹及百官列城內也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-12', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '漢改三川為河南郡，武帝置十三州，豫州舊名不改，以河南、河東二郡屬司隸，又以南陽屬荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-13', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '及劉聰攻陷洛陽，置左右司隸，各領戶二十餘萬，萬戶置一內史，凡內史四十三人，單于左右輔各主六夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-14', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '及武帝置十三州，其地以西偏為涼州，其餘並屬司隸，不統於州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-15', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '後罷，復置司隸校尉，統三輔如舊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-16', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '魏文帝即位，分河西為涼州，分隴右為秦州，改京兆尹為太守，馮翊、扶風各除左右，仍以三輔屬司隸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-17', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '於是乃於雍州置司隸校尉，以豫州刺史鎮許昌，秦州刺史鎮上邽，荊州刺史鎮豐陽，洛州刺史鎮宜陽，并州刺史鎮蒲坂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-18', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '苻堅時，分司隸為雍州，分京兆為咸陽郡，洛州刺史鎮陝城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-014-19', 'p0459', 'jinshu', 'a05-014', '《晉書·卷十四》', '及萇子興剋洛陽，以并、冀二州牧鎮蒲坂，豫州牧鎮洛陽，兗州刺史鎮倉垣，分司隸領北五郡，置雍州刺史鎮安定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-019-20', 'p0459', 'jinshu', 'a05-019', '《晉書·卷十九》', '魏元帝咸熙二年十二月甲子，使持節侍中太保鄭沖、兼太尉司隸校尉李憙奉皇帝璽綬策書，禪位于晉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-034-21', 'p0459', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '司隸校尉石鑒以宿憾奏預，免職。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-034-22', 'p0459', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '其後徵爲司隸校尉，加位特進，行次鄧縣而卒，時年六十三。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-037-23', 'p0459', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '任城景王陵字子山，宣帝弟魏司隸從事安城亭侯通之子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-039-24', 'p0459', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '其後浚布告天下，稱受中詔承制，乃以司空荀藩爲太尉，光祿大夫荀組爲司隸，大司農華薈爲太常，中書令李爲河南尹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-039-25', 'p0459', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '轉司隸校尉，加特進、光祿大夫，常侍如故。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-039-26', 'p0459', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '懷帝蒙塵，司空王浚以組爲司隸校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-039-27', 'p0459', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '愍帝稱皇太子，組即太子之舅，又領司隸校尉，行豫州刺史事，與藩並保滎陽之開封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0459-a05-039-28', 'p0459', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '俄而藩薨，帝更以組爲司空，領尚書左僕射，又兼司隸，復行留臺事，州征郡守皆承制行焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0460-a03-031-0', 'p0460', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '康固守，吏士有先受休假者，皆遁伏還赴，暮夜緣城而入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0460-a03-071-1', 'p0460', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0460-a04-008-2', 'p0460', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0460-a04-028-3', 'p0460', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」前至東門，東門復閉，乃使兵緣城攻門，州人悉走，因風放火，焚其府庫，遂殺綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0460-a04-055-4', 'p0460', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '寧手持練，身緣城，為吏士先，卒破獲朱光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a03-005-0', 'p0461', 'houhanshu', 'a03-005', '《後漢書·卷五》', '續漢志曰：「元初六年，以尚書歐陽家說，謂六宗者，在天地四方之中，為上下四方之宗，以元始中故事，謂六宗易六子之氣，日、月、雷公、風伯、山、澤者，非也，乃更六宗，祠於戌亥之地，禮比大社也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a03-071-1', 'p0461', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '雷公、浮雲、飛燕、白雀、楊鳳、于毒、五鹿、李大目、白繞、畦固、苦唒之徒，九州春秋「唒」作「蝤」，音才由反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a03-071-2', 'p0461', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '其大聲者稱雷公，騎白馬者為張白騎，輕便者言飛燕，多髭者號于氐根，左氏傳曰：「于思于思，棄甲復來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a03-097-3', 'p0461', 'houhanshu', 'a03-097', '《二十四史-後漢書-志第七‧祭祀上》', '背外營神，二十八宿外宮星，雷公、先農、風伯、雨師、四海、四瀆、名山、大川之屬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a03-098-4', 'p0461', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '以元始中故事，謂六宗易六子之氣日、月、雷公、風伯、山、澤者為非是。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a04-008-5', 'p0461', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a04-008-6', 'p0461', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '典略曰：黑山、黃巾諸帥，本非冠蓋，自相號字，謂騎白馬者為張白騎，謂輕捷者為張飛燕，謂聲大者為張雷公，其饒鬚者則自稱于羝根，其眼大者自稱李大目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a04-009-7', 'p0461', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '世語曰：初，爽夢二虎銜雷公，雷公若二升椀，放著庭中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a04-029-8', 'p0461', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '又天昨檄召五星，宣布星符，刺下東井，告命南箕，使召雷公、電父、風伯、雨師，羣岳吐陰，衆川激精，雲漢垂澤，蛟龍含靈，朱電，吐咀杳冥，殷殷雷聲，噓吸雨靈，習習谷風，六合皆同，欬唾之間，品物流形。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0461-a04-042-9', 'p0461', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '當造此劒之時，赤堇之山破而出錫，若邪之溪涸而出銅，雨師掃灑，雷公擊鼓，太一下觀，天精下之，歐冶乃因天之精，悉其技巧，一曰純鈎，二曰湛盧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0462-a03-018-0', 'p0462', 'houhanshu', 'a03-018', '《後漢書·卷十八》', '鄒陽曰：「神龍驤首奮翼，則浮雲出流。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0462-a03-039-1', 'p0462', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '伏見前司徒劉愷，沈重淵懿，道德博備，克讓爵土，致祚弱弟，躬浮雲之志，兼浩然之氣，孔子曰：「不義而富且貴，於我如浮雲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0462-a03-059-2', 'p0462', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '乘天潢之汎汎兮，浮雲漢之湯湯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0462-a03-071-3', 'p0462', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '雷公、浮雲、飛燕、白雀、楊鳳、于毒、五鹿、李大目、白繞、畦固、苦唒之徒，九州春秋「唒」作「蝤」，音才由反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0462-a03-080b-4', 'p0462', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '體迅輕鴻，榮曜春華，進如浮雲，退如激波。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0462-a04-008-5', 'p0462', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0462-a04-010-6', 'p0462', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧之功業，臣由以濟，用披浮雲，顯光日月。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0463-a03-071-0', 'p0463', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '雷公、浮雲、飛燕、白雀、楊鳳、于毒、五鹿、李大目、白繞、畦固、苦唒之徒，九州春秋「唒」作「蝤」，音才由反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0463-a04-065-1', 'p0463', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '退伏思惟，熒惑桑穀之異，天示二主，至於他餘錙介之妖，近是門庭小神所為，驗之天地，無有他變，而徵祥符瑞前後屢臻，明珠旣覿，白雀繼見，萬億之祚，實靈所挺，以九域為宅，天下為家，不與編戶之民轉徙同也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0464-a03-071-0', 'p0464', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '雷公、浮雲、飛燕、白雀、楊鳳、于毒、五鹿、李大目、白繞、畦固、苦唒之徒，九州春秋「唒」作「蝤」，音才由反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0464-a03-074-1', 'p0464', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '管子曰，齊桓公築五鹿、中牟、鄴，以禦諸侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0464-a03-110-2', 'p0464', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '五鹿墟，故沙鹿，左傳：「沙鹿崩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0464-a04-008-3', 'p0464', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0465-a03-071-0', 'p0465', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '雷公、浮雲、飛燕、白雀、楊鳳、于毒、五鹿、李大目、白繞、畦固、苦唒之徒，九州春秋「唒」作「蝤」，音才由反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0466-a04-008-0', 'p0466', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0467-a04-008-0', 'p0467', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '其後人衆寖廣，常山、趙郡、中山、上黨、河內諸山谷皆相通，其小帥孫輕、王當等，各以部衆從燕，衆至百萬，號曰黑山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0467-a04-017-1', 'p0467', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復從攻鄴，鄴破，遼別徇趙國、常山，招降緣山諸賊及黑山孫輕等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0468-a03-050-full-0', 'p0468', 'houhanshu', 'a03-050-full', '《後漢書·卷五十》', '忌等諂媚，云神言王當為天子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0468-a03-050-1', 'p0468', 'houhanshu', 'a03-050', '《後漢書·卷五十》', '忌等諂媚，云神言王當為天子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0468-a03-055-2', 'p0468', 'houhanshu', 'a03-055', '《後漢書·卷五十五》', '建和元年，甘陵人劉文與南郡妖賊劉鮪交通，訛言清河王當統天下，欲共立蒜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0468-a04-008-3', 'p0468', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '其後人衆寖廣，常山、趙郡、中山、上黨、河內諸山谷皆相通，其小帥孫輕、王當等，各以部衆從燕，衆至百萬，號曰黑山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0468-a04-020-4', 'p0468', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '有司奏王當就大理，朕惟公族甸師之義，不忍肆王市朝，故遣使者賜書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0468-a04-021-5', 'p0468', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '世子悵然自失，吳質耳曰：「王當行，流涕可也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0468-a04-032-6', 'p0468', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '易乾九五『飛龍在天』，大王當龍升，登帝位也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0468-a05-034-7', 'p0468', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '時人爲之語曰：「二王當國，羊公無德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0468-a05-037-8', 'p0468', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '然公私憲制，亦已有斷，王當以體國爲大，豈可尋繹由來，以亂朝憲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0469-a04-008-0', 'p0469', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹與公孫瓚爭兾州，燕遣將杜長等助瓚，與紹戰，為紹所敗，人衆稍散，太祖將定兾州，燕遣使求佐王師，拜平北將軍；率衆詣鄴，封安國亭侯，邑五百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0470-a04-006-0', 'p0470', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '乃引軍入朝歌鹿場山蒼巖谷討于毒，圍攻五日，破之，斬毒及長安所署兾州牧壺壽。');
